contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test a single call sequence: Put followed optionally by Collect.
    // params:
    //   uint putAmount - Ether amount to send to Put
    //   uint unlockTime - unlock time parameter to Put
    //   uint collectAmount - amount to attempt to Collect afterwards
    // The function is payable only to allow funding this contract for forwarding Ether to c.
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for put");
        // Read pre-state
        uint beforeAccBalance = c.Acc(address(this)).balance;
        uint beforeContractBal = address(c).balance;

        // Perform Put sending putAmount wei
        c.Put{value: putAmount}(unlockTime);

        // Read post-Put state
        uint afterAccBalance = c.Acc(address(this)).balance;
        uint afterContractBal = address(c).balance;

        // Now attempt Collect: must fund this test contract sufficiently to be able to receive Ether from c is not needed,
        // but Collect will send to msg.sender (which is this contract). We try-catch to observe success.
        bool collectedReverted;
        try c.Collect(collectAmount) {
            collectedReverted = false;
        } catch {
            collectedReverted = true;
        }

        // Read final recorded balance and contract balance
        uint finalAccBalance = c.Acc(address(this)).balance;
        uint finalContractBal = address(c).balance;

        // Assert general invariant combining Put and Collect behavior:
        // 1) Put must increase the recorded per-address balance and contract balance by exactly putAmount.
        // 2) If Collect succeeded (not reverted) then:
        //      a) collectAmount was <= before-recorded-after-Put balance (i.e., afterAccBalance)
        //      b) recorded balance decreased by exactly collectAmount and contract balance decreased by exactly collectAmount.
        //    If Collect reverted then recorded and contract balances remain unchanged from after the Put.
        assert(
            // Put effect holds
            afterAccBalance == beforeAccBalance + putAmount
            && afterContractBal == beforeContractBal + putAmount
            // Collect effect: either reverted and no change, or succeeded and decreased by collectAmount
            && (collectedReverted
                ? (finalAccBalance == afterAccBalance && finalContractBal == afterContractBal)
                : (
                    // success: ensure collectAmount was affordable by recorded balance before collect
                    afterAccBalance >= collectAmount
                    // and balances decreased by exactly collectAmount
                    && finalAccBalance == afterAccBalance - collectAmount
                    && finalContractBal == afterContractBal - collectAmount
                  )
               )
        );
    }

    // Allow receiving Ether from c during Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test: call Put (sending putAmount wei), then attempt Collect(collectAmount).
    // Params: putAmount must be available in this contract's balance to forward.
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for put");

        // Read pre-state: Acc(addr) returns (unlockTime, balance) via auto-generated getter for the struct.
        // The getter returns a tuple (uint,uint) where the second element is balance.
        (uint beforeUnlock, uint beforeAccBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put sending putAmount wei
        c.Put{value: putAmount}(unlockTime);

        // Read post-Put state
        (uint afterUnlock, uint afterAccBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Attempt Collect and observe whether it reverts
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final state
        (uint finalUnlock, uint finalAccBalance) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // General rule assertion:
        // 1) Put increased recorded balance and contract balance by exactly putAmount.
        // 2) If Collect succeeded: collectAmount <= balance before Collect (afterPut) and both balances decreased by exactly collectAmount.
        //    If Collect reverted: balances unchanged from after Put.
        assert(
            // Put effect
            afterAccBalance == beforeAccBalance + putAmount
            && afterContractBal == beforeContractBal + putAmount
            // Unlock time set to max(unlockTime, block.timestamp): hard to assert exact timestamp, but must be >= block.timestamp
            && afterUnlock >= block.timestamp
            // Collect effect depends on revert
            && (collectReverted
                ? (finalAccBalance == afterAccBalance && finalContractBal == afterContractBal && finalUnlock == afterUnlock)
                : (
                    // success: collectAmount was affordable and balances decreased exactly
                    afterAccBalance >= collectAmount
                    && finalAccBalance == afterAccBalance - collectAmount
                    && finalContractBal == afterContractBal - collectAmount
                    // unlock time should be unchanged by Collect
                    && finalUnlock == afterUnlock
                  )
               )
        );
    }

    // Allow receiving Ether from c during Collect
    receive() external payable {}
}

