contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: 1) deposit some ether with Put to ensure there is a balance >= MinSum,
    // 2) advance no time (block.timestamp stays as simulated), but we choose unlockTime in past so Collect may be allowed,
    // 3) call Collect with some amount and observe whether it reverts; if it succeeds we assert the conservation relation.

    // Parameters:
    // putAmount: amount of wei to forward to Put (must be available in this contract)
    // collectAmount: amount requested to Collect
    // requestedUnlock: unlock time parameter passed to Put
    function run(uint putAmount, uint collectAmount, uint requestedUnlock) public payable {
        // ensure test has funds to forward
        require(address(this).balance >= putAmount, "insufficient test balance");

        // Read recorded holder info before Put/Collect
        (uint beforeUnlock, uint beforeRecordedBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Make a Put to add funds and set unlock time
        c.Put{value: putAmount}(requestedUnlock);

        // After Put, read recorded balance again
        (uint midUnlock, uint midRecordedBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt Collect of collectAmount and record whether it reverted.
        bool reverted;
        // We expect this contract to be msg.sender for calls into c.
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        (uint afterUnlock, uint afterRecordedBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then:
        // - collectAmount must have been <= recorded balance before Collect (midRecordedBalance)
        // - the recorded balance after equals before minus the amount collected
        // - the contract's Ether balance decreased by exactly collectAmount
        // We cannot observe how much Ether this contract received directly inside the call (but address(this).balance increases exactly by that amount on success),
        // so assert the conservation: midRecordedBalance == afterRecordedBalance + collectAmount && midContractBal == afterContractBal + collectAmount
        assert(
            reverted || (
                // Collect succeeded branch: enforce conservation relations
                midRecordedBalance >= collectAmount
                && midRecordedBalance == afterRecordedBalance + collectAmount
                && midContractBal == afterContractBal + collectAmount
            )
        );
    }

    // Allow receiving Ether from C during tests
    receive() external payable {}
}

