    //    the recorded balance after equals before - collectAmount, and C's Ether balance decreased by exactly collectAmount.

    // Parameters:
    // putAmount: wei forwarded to Put
    // collectAmount: amount requested from Collect
    // requestedUnlock: unlockTime parameter for Put
    function run(uint putAmount, uint collectAmount, uint requestedUnlock) public payable {
