        // Read holder record and contract balance before any operations
        (uint beforeUnlock, uint beforeRecordedBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Deposit into the contract for this test contract's address
        c.Put{value: putAmount}(requestedUnlock);

        // Read mid-state (after Put, before Collect)
        (uint midUnlock, uint midRecordedBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
