        } catch {
            reverted = true;
        }

        // Read after-state
        (uint afterUnlock, uint afterRecordedBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then it must have transferred at most the recorded balance before Collect,
        // decreased the recorded balance by exactly the transferred amount, and decreased C's Ether balance by that amount.
        // Expressed as: if not reverted then midRecordedBalance >= collectAmount && midRecordedBalance == afterRecordedBalance + collectAmount && midContractBal == afterContractBal + collectAmount
        assert(
            reverted || (
                midRecordedBalance >= collectAmount
                && midRecordedBalance == afterRecordedBalance + collectAmount
                && midContractBal == afterContractBal + collectAmount
