contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property check
    // params: amount to attempt to collect, and an unlockTime to set beforehand
    function run(uint _putUnlockTime, uint _collectAmount) public payable {
        // make sure this test contract has enough ETH to do an initial Put if needed
        require(address(this).balance >= _collectAmount, "insufficient balance");

        // Ensure there is some deposit for this contract with unlockTime <= now so Collect can possibly succeed.
        // We first call Put to deposit some funds and set unlockTime to a time in the past (0) or supplied value.
        // Use try/catch to detect if Put reverted; we only proceed to test Collect regardless.
        bool putReverted;
        try c.Put{value: _collectAmount}(_putUnlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read observables before attempting Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeOnChain = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value:0}(_collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read observables after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterOnChain = address(c).balance;

        // If Collect succeeded, then recorded balance must decrease by exactly _collectAmount
        // and contract on-chain balance must also decrease by exactly _collectAmount.
        // If Collect reverted, observable state may be unchanged or changed by prior Put; we only assert the successful-case relation.
        assert( collectReverted || (afterBalance + _collectAmount == beforeBalance && afterOnChain + _collectAmount == beforeOnChain) );
    }

    receive() external payable {}
}

