    constructor(C _c) { c = _c; }

    // Call Put on c with an unlock time and an amount of Ether to send.
    // We assert that if the call does not revert, then c.Acc(address(this)).balance increases by exactly amount
    // and address(c).balance increases by exactly amount as well.
    function run(uint _unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read before-values via public getters
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        try c.Put{value: amount}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If the call reverted then nothing changed (balances remain equal to before)
        // If it did not revert then the recorded balance must have increased by exactly amount
        // and the contract's Ether balance must also have increased by exactly amount.
