contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to call Collect with an amount; we first ensure Acc[address(this)].balance >= MinSum and unlockTime in past
    function run(uint _initialPutUnlock, uint putAmount, uint collectAmount) public payable {
        // require enough Ether in this test contract to fund the Put call
        require(address(this).balance >= putAmount);

        // Initial read of this contract's Acc data and contract balance
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Make a Put to ensure there is sufficient recorded balance and unlockTime can be set
        // We set unlock time to a past or future time via _initialPutUnlock; if it's <= block.timestamp Put will set unlockTime to block.timestamp.
        bool putReverted;
        try c.Put{value: putAmount}(_initialPutUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read values after Put
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // We attempt Collect irrespective of Put reverting; capture whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
