        // and (2) the contract's Ether balance decreased by at least collectAmount (it may decrease more due to other transfers),
        // and (3) unlock time for this account is unchanged by Collect.
        // If Collect reverted then state remains unchanged from just before the Collect call.
        assert(
            (collectReverted && afterBalance == midBalance && afterContractBal == midContractBal && afterUnlock == midUnlock)
            || (!collectReverted && afterBalance + collectAmount == midBalance && midContractBal >= afterContractBal && afterUnlock == midUnlock)
        );
